<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/core/unified.php';
require_once dirname(__DIR__) . '/maifip/app_version.php';
if (empty($_SESSION['user']['id']) || (string)($_SESSION['fams_system'] ?? '') !== 'portal') { header('Location: ../auth/login.php'); exit; }
if (!fams_validate_lpgma_session() || !fams_is_lpgma_role((string)($_SESSION['user']['role'] ?? ''))) { header('Location: ../auth/login.php'); exit; }
$name = (string)($_SESSION['user']['full_name'] ?? 'LPGMA User');
$token = (string)($_SESSION['portal_csrf'] ??= bin2hex(random_bytes(32)));
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($token, (string)($_POST['csrf_token'] ?? ''))) { http_response_code(419); exit('Invalid request token. Refresh and try again.'); }
    $target = (string)($_POST['workspace'] ?? '');
    if ($target === 'maifip') { header('Location: ../maifip/switch.php'); exit; }
    if ($target === 'aics') { header('Location: ../aics/switch.php?to=aics'); exit; }
    http_response_code(400); exit('Invalid workspace selection.');
}
function portal_e(string $s): string { return htmlspecialchars($s, ENT_QUOTES, 'UTF-8'); }
?>
